// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    address actor;

    function setUp() public {
        actor = makeAddr("actor");
        c = new StaxLPStaking(address(this), address(this));
    }

    function testFuzz_property(address _newOwner) public {
        vm.assume(_newOwner != address(0));

        c.transferOwnership(_newOwner);

        bool success;
        vm.prank(_newOwner);
        try c.renounceOwnership() {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(success);
    }
}
